"""Migration of the Meridian CRM 4.2 order_fulfilment workflow."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion for the values used by this workflow."""
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value).strip() or "0")
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup_credit_hold(record: dict, tables: dict) -> str:
    """Implement VRL LOOKUP over the first live ACCT_MASTER row."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            value = row.get("CRED_HOLD", "")
            return "" if value is None else value
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order_fulfilment transition in document order."""
    result_record = dict(record)

    if state == "E" and event == "approve":
        if _numeric(record.get("TOT_AMT", "")) > Decimal("0"):
            return {
                "state": "A",
                "record": result_record,
                "audits": ["ORD_APPR"],
                "notifies": [],
                "matched": True,
            }

    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": result_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": result_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "cancel":
        if _lookup_credit_hold(record, tables) != "Y":
            return {
                "state": "X",
                "record": result_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
